-- US occupation profiles from O*NET 29.1 (CC BY 4.0). Source row inserted first; replace the id if re-seeding elsewhere.
insert into public.sources(id,url,publisher,title,license,retrieved_at) values ('84650b67-bf2a-43dd-9ddd-f7525c933c75','https://www.onetcenter.org/database.html','National Center for O*NET Development','O*NET 29.1 Database (Nov 2024): Occupation Data, Task Statements and Ratings, Education Training and Experience, Knowledge','CC BY 4.0','2026-11-26');
with v(soc,onet,description,tasks,topics,path) as (values
('47-2011','47-2011.00','{"en": "Construct, assemble, maintain, and repair stationary steam boilers and boiler house auxiliaries. Align structures or plate sections to assemble boiler frame tanks or vats, following blueprints. Work involves use of hand and power tools, plumb bobs, levels, wedges, dogs, or turnbuckles. Assist in testing assembled vessels. Direct cleaning of boilers and boiler furnaces. Inspect and repair boiler fittings, such as safety valves, regulators, automatic-control mechanisms, water columns, and auxiliary machines."}'::jsonb,'["Attach rigging and signal crane or hoist operators to lift heavy frame and plate sections or other parts into place.", "Study blueprints to determine locations, relationships, or dimensions of parts.", "Repair or replace defective pressure vessel parts, such as safety valves or regulators, using torches, jacks, caulking hammers, power saws, threading dies, welding equipment, or metalworking machinery.", "Locate and mark reference points for columns or plates on boiler foundations, following blueprints and using straightedges, squares, transits, or measuring instruments.", "Bolt or arc weld pressure vessel structures and parts together, using wrenches or welding equipment."]'::jsonb,'["Mathematics", "Design", "Building and Construction", "Production and Processing", "Mechanical"]'::jsonb,'{"job_zone": 3, "education": {"label": "No high school diploma", "pct": 39}, "experience": {"label": "1 to 2 years", "pct": 38}, "onsite_training": {"label": "6 months to 1 year", "pct": 32}, "on_the_job": {"label": "6 months to 1 year", "pct": 43}}'::jsonb),
('47-2021','47-2021.00','{"en": "Lay and bind building materials, such as brick, structural tile, concrete block, cinder block, glass block, and terra-cotta block, with mortar and other substances, to construct or repair walls, partitions, arches, sewers, and other structures."}'::jsonb,'["Measure distance from reference points and mark guidelines to lay out work, using plumb bobs and levels.", "Construct corners by fastening in plumb position a corner pole or building a corner pyramid of bricks, and filling in between the corners using a line from corner to corner to guide each course, or layer, of brick.", "Apply and smooth mortar or other mixture over work surface.", "Calculate angles and courses and determine vertical and horizontal alignment of courses.", "Break or cut bricks, tiles, or blocks to size, using trowel edge, hammer, or power saw."]'::jsonb,'["Building and Construction", "Mathematics", "English Language", "Public Safety and Security", "Production and Processing"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 70}, "experience": {"label": "2 to 4 years", "pct": 36}, "onsite_training": {"label": "2 to 4 years", "pct": 36}, "on_the_job": {"label": "2 to 4 years", "pct": 40}}'::jsonb),
('47-2082','47-2082.00','{"en": "Seal joints between plasterboard or other wallboard to prepare wall surface for painting or papering."}'::jsonb,'["Spread sealing compound between boards or panels or over cracks, holes, nail heads, or screw heads, using trowels, broadknives, or spatulas.", "Press paper tape over joints to embed tape into sealing compound and to seal joints.", "Apply additional coats to fill in holes and make surfaces smooth.", "Seal joints between plasterboard or other wallboard to prepare wall surfaces for painting or papering.", "Spread and smooth cementing material over tape, using trowels or floating machines to blend joints with wall surfaces."]'::jsonb,'["Building and Construction", "English Language", "Education and Training", "Customer and Personal Service", "Mechanical"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 46}, "experience": {"label": "1 to 2 years", "pct": 35}, "onsite_training": {"label": "2 to 4 years", "pct": 41}, "on_the_job": {"label": "2 to 4 years", "pct": 31}}'::jsonb),
('47-2111','47-2111.00','{"en": "Install, maintain, and repair electrical wiring, equipment, and fixtures. Ensure that work is in accordance with relevant codes. May install or service street lights, intercom systems, or electrical control systems."}'::jsonb,'["Prepare sketches or follow blueprints to determine the location of wiring or equipment and to ensure conformance to building and safety codes.", "Place conduit, pipes, or tubing, inside designated partitions, walls, or other concealed areas, and pull insulated wires or cables through the conduit to complete circuits between boxes.", "Work from ladders, scaffolds, or roofs to install, maintain, or repair electrical wiring, equipment, or fixtures.", "Use a variety of tools or equipment, such as power construction equipment, measuring devices, power tools, and testing equipment, such as oscilloscopes, ammeters, or test lamps.", "Assemble, install, test, or maintain electrical or electronic wiring, equipment, appliances, apparatus, or fixtures, using hand tools or power tools."]'::jsonb,'["Building and Construction", "Administration and Management", "Mechanical", "Mathematics", "Design"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 62}, "experience": {"label": "6 months to 1 year", "pct": 28}, "onsite_training": {"label": "Up to 1 month", "pct": 24}, "on_the_job": {"label": "4 to 10 years", "pct": 37}}'::jsonb),
('47-2152','47-2152.00','{"en": "Assemble, install, alter, and repair pipelines or pipe systems that carry water, steam, air, or other liquids or gases. May install heating and cooling equipment and mechanical control systems. Includes sprinkler fitters."}'::jsonb,'["Shut off steam, water, or other gases or liquids from pipe sections, using valve keys or wrenches.", "Install underground storm, sanitary, or water piping systems, extending piping as needed to connect fixtures and plumbing.", "Assemble pipe sections, tubing, or fittings, using couplings, clamps, screws, bolts, cement, plastic solvent, caulking, or soldering, brazing, or welding equipment.", "Locate and mark the position of pipe installations, connections, passage holes, or fixtures in structures, using measuring instruments such as rulers or levels.", "Cut, thread, or hammer pipes to specifications, using tools such as saws, cutting torches, pipe threaders, or pipe benders."]'::jsonb,'["Building and Construction", "Mechanical", "Design", "Mathematics", "Customer and Personal Service"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 43}, "experience": {"label": "4 to 6 years", "pct": 57}, "onsite_training": {"label": "4 to 10 years", "pct": 33}, "on_the_job": {"label": "4 to 10 years", "pct": 33}}'::jsonb),
('47-2211','47-2211.00','{"en": "Fabricate, assemble, install, and repair sheet metal products and equipment, such as ducts, control boxes, drainpipes, and furnace casings. Work may involve any of the following: setting up and operating fabricating machines to cut, bend, and straighten sheet metal; shaping metal over anvils, blocks, or forms using hammer; operating soldering and welding equipment to join sheet metal parts; or inspecting, assembling, and smoothing seams and joints of burred surfaces. Includes sheet metal duct installers who install prefabricated sheet metal ducts used for heating, air conditioning, or other purposes."}'::jsonb,'["Maintain equipment, making repairs or modifications when necessary.", "Fabricate ducts for high efficiency heating, ventilating, and air conditioning (HVAC) systems to maximize efficiency of systems.", "Fasten seams or joints together with welds, bolts, cement, rivets, solder, caulks, metal drive clips, or bonds to assemble components into products or to repair sheet metal items.", "Transport prefabricated parts to construction sites for assembly and installation.", "Install assemblies, such as flashing, pipes, tubes, heating and air conditioning ducts, furnace casings, rain gutters, or downspouts in supportive frameworks."]'::jsonb,'["Mechanical", "Building and Construction", "Mathematics", "Design", "English Language"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 49}, "experience": {"label": "None", "pct": 47}, "onsite_training": {"label": "4 to 10 years", "pct": 19}, "on_the_job": {"label": "2 to 4 years", "pct": 40}}'::jsonb),
('47-2221','47-2221.00','{"en": "Raise, place, and unite iron or steel girders, columns, and other structural members to form completed structures or structural frameworks. May erect metal storage tanks and assemble prefabricated metal buildings."}'::jsonb,'["Read specifications or blueprints to determine the locations, quantities, or sizes of materials required.", "Connect columns, beams, and girders with bolts, following blueprints and instructions from supervisors.", "Bolt aligned structural steel members in position for permanent riveting, bolting, or welding into place.", "Fasten structural steel members to hoist cables, using chains, cables, or rope.", "Hoist steel beams, girders, or columns into place, using cranes or signaling hoisting equipment operators to lift and position structural steel members."]'::jsonb,'["Building and Construction", "Mechanical", "Mathematics", "Public Safety and Security", "Administration and Management"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 42}, "experience": {"label": "None", "pct": 33}, "onsite_training": {"label": "Up to 1 month", "pct": 48}, "on_the_job": {"label": "Up to 1 month", "pct": 23}}'::jsonb),
('47-4011','47-4011.00','{"en": "Inspect structures using engineering skills to determine structural soundness and compliance with specifications, building codes, and other regulations. Inspections may be general in nature or may be limited to a specific area, such as electrical systems or plumbing."}'::jsonb,'["Approve building plans that meet required specifications.", "Review and interpret plans, blueprints, site layouts, specifications, or construction methods to ensure compliance to legal requirements and safety regulations.", "Issue permits for construction, relocation, demolition, or occupancy.", "Inspect bridges, dams, highways, buildings, wiring, plumbing, electrical circuits, sewers, heating systems, or foundations during and after construction for structural quality, general safety, or conformance to specifications and codes.", "Monitor installation of plumbing, wiring, equipment, or appliances to ensure that installation is performed properly and is in compliance with applicable regulations."]'::jsonb,'["Building and Construction", "Public Safety and Security", "English Language", "Customer and Personal Service", "Law and Government"]'::jsonb,'{"job_zone": 3, "education": {"label": "High school diploma or GED", "pct": 36}, "experience": {"label": "4 to 6 years", "pct": 32}, "onsite_training": {"label": "3 to 6 months", "pct": 20}, "on_the_job": {"label": "3 to 6 months", "pct": 24}}'::jsonb),
('47-4021','47-4021.00','{"en": "Assemble, install, repair, or maintain electric or hydraulic freight or passenger elevators, escalators, or dumbwaiters."}'::jsonb,'["Inspect wiring connections, control panel hookups, door installations, and alignments and clearances of cars and hoistways to ensure that equipment will operate properly.", "Assemble, install, repair, and maintain elevators, escalators, moving sidewalks, and dumbwaiters, using hand and power tools, and testing devices such as test lamps, ammeters, and voltmeters.", "Disassemble defective units, and repair or replace parts such as locks, gears, cables, and electric wiring.", "Check that safety regulations and building codes are met, and complete service reports verifying conformance to standards.", "Locate malfunctions in brakes, motors, switches, and signal and control systems, using test equipment."]'::jsonb,'["Mechanical", "Customer and Personal Service", "Building and Construction", "Public Safety and Security", "Computers and Electronics"]'::jsonb,'{"job_zone": 3, "education": {"label": "High school diploma or GED", "pct": 47}, "experience": {"label": "2 to 4 years", "pct": 29}, "onsite_training": {"label": "1 to 3 months", "pct": 34}, "on_the_job": {"label": "4 to 10 years", "pct": 32}}'::jsonb),
('49-2091','49-2091.00','{"en": "Install, inspect, test, adjust, or repair avionics equipment, such as radar, radio, navigation, and missile control systems in aircraft or space vehicles."}'::jsonb,'["Test and troubleshoot instruments, components, and assemblies, using circuit testers, oscilloscopes, or voltmeters.", "Keep records of maintenance and repair work.", "Adjust, repair, or replace malfunctioning components or assemblies, using hand tools or soldering irons.", "Install electrical and electronic components, assemblies, and systems in aircraft, using hand tools, power tools, or soldering irons.", "Set up and operate ground support and test equipment to perform functional flight tests of electrical and electronic systems."]'::jsonb,'["Computers and Electronics", "Mechanical", "English Language", "Engineering and Technology", "Customer and Personal Service"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 50}, "experience": {"label": "2 to 4 years", "pct": 31}, "onsite_training": {"label": "Up to 1 month", "pct": 41}, "on_the_job": {"label": "3 to 6 months", "pct": 29}}'::jsonb),
('49-2095','49-2095.00','{"en": "Inspect, test, repair, or maintain electrical equipment in generating stations, substations, and in-service relays."}'::jsonb,'["Inspect and test equipment and circuits to identify malfunctions or defects, using wiring diagrams and testing devices such as ohmmeters, voltmeters, or ammeters.", "Prepare and maintain records detailing tests, repairs, and maintenance.", "Consult manuals, schematics, wiring diagrams, and engineering personnel to troubleshoot and solve equipment problems and to determine optimum equipment functioning.", "Analyze test data to diagnose malfunctions, to determine performance characteristics of systems, or to evaluate effects of system modifications.", "Open and close switches to isolate defective relays, performing adjustments or repairs."]'::jsonb,'["Mechanical", "Mathematics", "Engineering and Technology", "Public Safety and Security", "English Language"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 50}, "experience": {"label": "2 to 4 years", "pct": 35}, "onsite_training": {"label": "2 to 4 years", "pct": 40}, "on_the_job": {"label": "2 to 4 years", "pct": 53}}'::jsonb))
insert into public.occupation_profiles(occupation_id,country_code,description,tasks,study_topics,typical_path,external_code,source_id,as_of)
select c.occupation_id,'US',v.description,v.tasks,v.topics,v.path,v.onet,'84650b67-bf2a-43dd-9ddd-f7525c933c75','2024-11-01'
from v join public.occupation_codes c on c.country_code='US' and c.code=v.soc;
with v(soc,onet,description,tasks,topics,path) as (values
('49-3011','49-3011.00','{"en": "Diagnose, adjust, repair, or overhaul aircraft engines and assemblies, such as hydraulic and pneumatic systems."}'::jsonb,'["Examine and inspect aircraft components, including landing gear, hydraulic systems, and deicers to locate cracks, breaks, leaks, or other problems.", "Conduct routine and special inspections as required by regulations.", "Inspect completed work to certify that maintenance meets standards and that aircraft are ready for operation.", "Read and interpret maintenance manuals, service bulletins, and other specifications to determine the feasibility and method of repairing or replacing malfunctioning or damaged components.", "Maintain repair logs, documenting all preventive and corrective aircraft maintenance."]'::jsonb,'["Mechanical", "English Language", "Engineering and Technology", "Customer and Personal Service", "Mathematics"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 60}, "experience": {"label": "2 to 4 years", "pct": 31}, "onsite_training": {"label": "Up to 1 month", "pct": 37}, "on_the_job": {"label": "6 months to 1 year", "pct": 39}}'::jsonb),
('49-3031','49-3031.00','{"en": "Diagnose, adjust, repair, or overhaul buses and trucks, or maintain and repair any type of diesel engines. Includes mechanics working primarily with automobile or marine diesel engines."}'::jsonb,'["Use handtools, such as screwdrivers, pliers, wrenches, pressure gauges, or precision instruments, as well as power tools, such as pneumatic wrenches, lathes, welding equipment, or jacks and hoists.", "Inspect brake systems, steering mechanisms, wheel bearings, and other important parts to ensure that they are in proper operating condition.", "Raise trucks, buses, and heavy parts or equipment using hydraulic jacks or hoists.", "Adjust and reline brakes, align wheels, tighten bolts and screws, and reassemble equipment.", "Attach test instruments to equipment, and read dials and gauges to diagnose malfunctions."]'::jsonb,'["Mechanical", "Transportation", "Education and Training", "English Language", "Public Safety and Security"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 39}, "experience": {"label": "1 to 2 years", "pct": 35}, "onsite_training": {"label": "1 to 2 years", "pct": 38}, "on_the_job": {"label": "1 to 2 years", "pct": 41}}'::jsonb),
('49-3042','49-3042.00','{"en": "Diagnose, adjust, repair, or overhaul mobile mechanical, hydraulic, and pneumatic equipment, such as cranes, bulldozers, graders, and conveyors, used in construction, logging, and mining."}'::jsonb,'["Repair and replace damaged or worn parts.", "Test mechanical products and equipment after repair or assembly to ensure proper performance and compliance with manufacturers'' specifications.", "Operate and inspect machines or heavy equipment to diagnose defects.", "Read and understand operating manuals, blueprints, and technical drawings.", "Dismantle and reassemble heavy equipment using hoists and hand tools."]'::jsonb,'["Mechanical", "Customer and Personal Service", "Mathematics", "Computers and Electronics", "Public Safety and Security"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 55}, "experience": {"label": "2 to 4 years", "pct": 34}, "onsite_training": {"label": "1 to 2 years", "pct": 28}, "on_the_job": {"label": "6 months to 1 year", "pct": 26}}'::jsonb),
('49-9041','49-9041.00','{"en": "Repair, install, adjust, or maintain industrial production and processing machinery or refinery and pipeline distribution systems. May also install, dismantle, or move machinery and heavy equipment according to plans."}'::jsonb,'["Repair or maintain the operating condition of industrial production or processing machinery or equipment.", "Repair or replace broken or malfunctioning components of machinery or equipment.", "Clean, lubricate, or adjust parts, equipment, or machinery.", "Disassemble machinery or equipment to remove parts and make repairs.", "Reassemble equipment after completion of inspections, testing, or repairs."]'::jsonb,'["Mechanical", "English Language", "Production and Processing", "Engineering and Technology", "Design"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 47}, "experience": {"label": "1 to 2 years", "pct": 32}, "onsite_training": {"label": "1 to 2 years", "pct": 26}, "on_the_job": {"label": "1 to 2 years", "pct": 29}}'::jsonb),
('49-9044','49-9044.00','{"en": "Install, dismantle, or move machinery and heavy equipment according to layout plans, blueprints, or other drawings."}'::jsonb,'["Replace defective parts of machine, or adjust clearances and alignment of moving parts.", "Align machines or equipment, using hoists, jacks, hand tools, squares, rules, micrometers, lasers, or plumb bobs.", "Insert shims, adjust tension on nuts and bolts, or position parts, using hand tools and measuring instruments, to set specified clearances between moving and stationary parts.", "Signal crane operator to lower basic assembly units to bedplate, and align unit to centerline.", "Conduct preventative maintenance and repair, and lubricate machines and equipment."]'::jsonb,'["Mechanical", "Mathematics", "Building and Construction", "Education and Training", "Engineering and Technology"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 45}, "experience": {"label": "4 to 6 years", "pct": 27}, "onsite_training": {"label": "2 to 4 years", "pct": 27}, "on_the_job": {"label": "2 to 4 years", "pct": 38}}'::jsonb),
('49-9051','49-9051.00','{"en": "Install or repair cables or wires used in electrical power or distribution systems. May erect poles and light or heavy duty transmission towers."}'::jsonb,'["Adhere to safety practices and procedures, such as checking equipment regularly and erecting barriers around work areas.", "Drive vehicles equipped with tools and materials to job sites.", "Open switches or attach grounding devices to remove electrical hazards from disturbed or fallen lines or to facilitate repairs.", "Climb poles or use truck-mounted buckets to access equipment.", "Install, maintain, and repair electrical distribution and transmission systems, including conduits, cables, wires, and related equipment, such as transformers, circuit breakers, and switches."]'::jsonb,'["Building and Construction", "English Language", "Education and Training", "Public Safety and Security", "Transportation"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 50}, "experience": {"label": "None", "pct": 39}, "onsite_training": {"label": "Up to 1 month", "pct": 18}, "on_the_job": {"label": "4 to 10 years", "pct": 27}}'::jsonb),
('49-9052','49-9052.00','{"en": "Install and repair telecommunications cable, including fiber optics."}'::jsonb,'["Set up service for customers, installing, connecting, testing, or adjusting equipment.", "Travel to customers'' premises to install, maintain, or repair audio and visual electronic reception equipment or accessories.", "Measure signal strength at utility poles, using electronic test equipment.", "Inspect or test lines or cables, recording and analyzing test results, to assess transmission characteristics and locate faults or malfunctions.", "Splice cables, using hand tools, epoxy, or mechanical equipment."]'::jsonb,'["Telecommunications", "Customer and Personal Service", "English Language", "Public Safety and Security", "Computers and Electronics"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 60}, "experience": {"label": "None", "pct": 35}, "onsite_training": {"label": "1 to 3 months", "pct": 27}, "on_the_job": {"label": "1 to 3 months", "pct": 26}}'::jsonb),
('49-9081','49-9081.00','{"en": "Inspect, diagnose, adjust, or repair wind turbines. Perform maintenance on wind turbine equipment including resolving electrical, mechanical, and hydraulic malfunctions."}'::jsonb,'["Troubleshoot or repair mechanical, hydraulic, or electrical malfunctions related to variable pitch systems, variable speed control systems, converter systems, or related components.", "Perform routine maintenance on wind turbine equipment, underground transmission systems, wind fields substations, or fiber optic sensing and control systems.", "Diagnose problems involving wind turbine generators or control systems.", "Test electrical components of wind systems with devices, such as voltage testers, multimeters, oscilloscopes, infrared testers, or fiber optic equipment.", "Start or restart wind turbine generator systems to ensure proper operations."]'::jsonb,'["Mechanical", "Computers and Electronics", "English Language", "Public Safety and Security", "Engineering and Technology"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 34}, "experience": {"label": "1 to 2 years", "pct": 32}, "onsite_training": {"label": "6 months to 1 year", "pct": 26}, "on_the_job": {"label": "6 months to 1 year", "pct": 46}}'::jsonb),
('49-9092','49-9092.00','{"en": "Work below surface of water, using surface-supplied air or scuba equipment to inspect, repair, remove, or install equipment and structures. May use a variety of power and hand tools, such as drills, sledgehammers, torches, and welding equipment. May conduct tests or experiments, rig explosives, or photograph structures or marine life."}'::jsonb,'["Take appropriate safety precautions, such as monitoring dive lengths and depths and registering with authorities before diving expeditions begin.", "Check and maintain diving equipment, such as helmets, masks, air tanks, harnesses, or gauges.", "Communicate with workers on the surface while underwater, using signal lines or telephones.", "Descend into water with the aid of diver helpers, using scuba gear or diving suits.", "Obtain information about diving tasks and environmental conditions."]'::jsonb,'["Mechanical", "Building and Construction", "Physics", "Customer and Personal Service", "Mathematics"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 72}, "experience": {"label": "None", "pct": 25}, "onsite_training": {"label": "Up to 1 month", "pct": 26}, "on_the_job": {"label": "None or short demonstration", "pct": 23}}'::jsonb),
('49-9096','49-9096.00','{"en": "Set up or repair rigging for construction projects, manufacturing plants, logging yards, ships and shipyards, or for the entertainment industry."}'::jsonb,'["Test rigging to ensure safety and reliability.", "Signal or verbally direct workers engaged in hoisting and moving loads to ensure safety of workers and materials.", "Control movement of heavy equipment through narrow openings or confined spaces, using chainfalls, gin poles, gallows frames, and other equipment.", "Tilt, dip, and turn suspended loads to maneuver over, under, or around obstacles, using multi-point suspension techniques.", "Select gear, such as cables, pulleys, and winches, according to load weights and sizes, facilities, and work schedules."]'::jsonb,'["Mechanical", "Public Safety and Security", "Production and Processing", "Customer and Personal Service", "Administration and Management"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 63}, "experience": {"label": "None", "pct": 34}, "onsite_training": {"label": "3 to 6 months", "pct": 21}, "on_the_job": {"label": "3 to 6 months", "pct": 26}}'::jsonb),
('49-9097','49-9097.00','{"en": "Install, inspect, test, maintain, or repair electric gate crossings, signals, signal equipment, track switches, section lines, or intercommunications systems within a railroad system."}'::jsonb,'["Inspect and test operation, mechanical parts, and circuitry of gate crossings, signals, and signal equipment such as interlocks and hotbox detectors.", "Inspect electrical units of railroad grade crossing gates and repair loose bolts and defective electrical connections and parts.", "Test and repair track circuits.", "Drive motor vehicles to job sites.", "Install, inspect, maintain, and repair various railroad service equipment on the road or in the shop, including railroad signal systems."]'::jsonb,'["Transportation", "Mechanical", "English Language", "Public Safety and Security", "Telecommunications"]'::jsonb,'{"job_zone": 3, "education": {"label": "No high school diploma", "pct": 34}, "experience": {"label": "2 to 4 years", "pct": 19}, "onsite_training": {"label": "6 months to 1 year", "pct": 24}, "on_the_job": {"label": "3 to 6 months", "pct": 23}}'::jsonb))
insert into public.occupation_profiles(occupation_id,country_code,description,tasks,study_topics,typical_path,external_code,source_id,as_of)
select c.occupation_id,'US',v.description,v.tasks,v.topics,v.path,v.onet,'84650b67-bf2a-43dd-9ddd-f7525c933c75','2024-11-01'
from v join public.occupation_codes c on c.country_code='US' and c.code=v.soc;
with v(soc,onet,description,tasks,topics,path) as (values
('51-4111','51-4111.00','{"en": "Analyze specifications, lay out metal stock, set up and operate machine tools, and fit and assemble parts to make and repair dies, cutting tools, jigs, fixtures, gauges, and machinists'' hand tools."}'::jsonb,'["Verify dimensions, alignments, and clearances of finished parts for conformance to specifications, using measuring instruments such as calipers, gauge blocks, micrometers, or dial indicators.", "Set up and operate conventional or computer numerically controlled machine tools such as lathes, milling machines, or grinders to cut, bore, grind, or otherwise shape parts to prescribed dimensions and finishes.", "Visualize and compute dimensions, sizes, shapes, and tolerances of assemblies, based on specifications.", "Study blueprints, sketches, models, or specifications to plan sequences of operations for fabricating tools, dies, or assemblies.", "Fit and assemble parts to make, repair, or modify dies, jigs, gauges, and tools, using machine tools, hand tools, or welders."]'::jsonb,'["Mechanical", "Mathematics", "Production and Processing", "Design", "English Language"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 41}, "experience": {"label": "4 to 6 years", "pct": 25}, "onsite_training": {"label": "6 months to 1 year", "pct": 24}, "on_the_job": {"label": "1 to 2 years", "pct": 28}}'::jsonb),
('51-8013','51-8013.00','{"en": "Control, operate, or maintain machinery to generate electric power. Includes auxiliary equipment operators."}'::jsonb,'["Control generator output to match the phase, frequency, or voltage of electricity supplied to panels.", "Take regulatory action, based on readings from charts, meters and gauges, at established intervals.", "Control power generating equipment, including boilers, turbines, generators, or reactors, using control boards or semi-automatic equipment.", "Start or stop generators, auxiliary pumping equipment, turbines, or other power plant equipment as necessary.", "Monitor power plant equipment and indicators to detect evidence of operating problems."]'::jsonb,'["Mechanical", "Public Safety and Security", "English Language", "Production and Processing", "Chemistry"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 60}, "experience": {"label": "2 to 4 years", "pct": 47}, "onsite_training": {"label": "2 to 4 years", "pct": 37}, "on_the_job": {"label": "2 to 4 years", "pct": 50}}'::jsonb),
('51-8021','51-8021.00','{"en": "Operate or maintain stationary engines, boilers, or other mechanical equipment to provide utilities for buildings or industrial processes. Operate equipment such as steam engines, generators, motors, turbines, and steam boilers."}'::jsonb,'["Operate or tend stationary engines, boilers, and auxiliary equipment, such as pumps, compressors, or air-conditioning equipment, to supply and maintain steam or heat for buildings, marine vessels, or pneumatic tools.", "Activate valves to maintain required amounts of water in boilers, to adjust supplies of combustion air, and to control the flow of fuel into burners.", "Monitor boiler water, chemical, and fuel levels, and make adjustments to maintain required levels.", "Analyze problems and take appropriate action to ensure continuous and reliable operation of equipment and systems.", "Observe and interpret readings on gauges, meters, and charts registering various aspects of boiler operation to ensure that boilers are operating properly."]'::jsonb,'["Mechanical", "Chemistry", "Public Safety and Security", "Physics", "Engineering and Technology"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 47}, "experience": {"label": "1 to 2 years", "pct": 24}, "onsite_training": {"label": "6 months to 1 year", "pct": 51}, "on_the_job": {"label": "6 months to 1 year", "pct": 41}}'::jsonb),
('51-8091','51-8091.00','{"en": "Control or operate entire chemical processes or system of machines."}'::jsonb,'["Monitor recording instruments, flowmeters, panel lights, or other indicators and listen for warning signals to verify conformity of process conditions.", "Regulate or shut down equipment during emergency situations, as directed by supervisory personnel.", "Control or operate chemical processes or systems of machines, using panelboards, control boards, or semi-automatic equipment.", "Move control settings to make necessary adjustments on equipment units affecting speeds of chemical reactions, quality, or yields.", "Inspect operating units, such as towers, soap-spray storage tanks, scrubbers, collectors, or driers to ensure that all are functioning and to maintain maximum efficiency."]'::jsonb,'["Production and Processing", "Chemistry", "Mechanical", "English Language", "Public Safety and Security"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 62}, "experience": {"label": "4 to 6 years", "pct": 24}, "onsite_training": {"label": "6 months to 1 year", "pct": 51}, "on_the_job": {"label": "3 to 6 months", "pct": 32}}'::jsonb),
('51-8092','51-8092.00','{"en": "Distribute or process gas for utility companies and others by controlling compressors to maintain specified pressures on main pipelines."}'::jsonb,'["Monitor equipment functioning, observe temperature, level, and flow gauges, and perform regular unit checks to ensure that all equipment is operating as it should.", "Distribute or process gas for utility companies or industrial plants, using panel boards, control boards, and semi-automatic equipment.", "Control operation of compressors, scrubbers, evaporators, and refrigeration equipment to liquefy, compress, or regasify natural gas.", "Control equipment to regulate flow and pressure of gas to feedlines of boilers, furnaces, and related steam-generating or heating equipment.", "Record, review, and compile operations records, test results, and gauge readings such as temperatures, pressures, concentrations, and flows."]'::jsonb,'["Public Safety and Security", "Mechanical", "English Language", "Computers and Electronics", "Mathematics"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 58}, "experience": {"label": "1 to 2 years", "pct": 51}, "onsite_training": {"label": "1 to 2 years", "pct": 40}, "on_the_job": {"label": "6 months to 1 year", "pct": 46}}'::jsonb),
('51-8093','51-8093.00','{"en": "Operate or control petroleum refining or processing units. May specialize in controlling manifold and pumping systems, gauging or testing oil in storage tanks, or regulating the flow of oil into pipelines."}'::jsonb,'["Signal other workers by telephone or radio to operate pumps, open and close valves, and check temperatures.", "Maintain and repair equipment, or report malfunctioning equipment to supervisors so that repairs can be scheduled.", "Monitor process indicators, instruments, gauges, and meters to detect and report any possible problems.", "Start pumps and open valves or use automated equipment to regulate the flow of oil in pipelines and into and out of tanks.", "Operate control panels to coordinate and regulate process variables such as temperature and pressure, and to direct product flow rate, according to process schedules."]'::jsonb,'["Production and Processing", "Public Safety and Security", "Mechanical", "Administration and Management", "Mathematics"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 97}, "experience": {"label": "1 to 2 years", "pct": 19}, "onsite_training": {"label": "Up to 1 month", "pct": 30}, "on_the_job": {"label": "3 to 6 months", "pct": 43}}'::jsonb),
('51-9162','51-9162.00','{"en": "Develop programs to control machining or processing of materials by automatic machine tools, equipment, or systems. May also set up, operate, or maintain equipment."}'::jsonb,'["Write programs in the language of a machine''s controller and store programs on media, such as punch tapes, magnetic tapes, or disks.", "Determine the sequence of machine operations, and select the proper cutting tools needed to machine workpieces into the desired shapes.", "Revise programs or tapes to eliminate errors, and retest programs to check that problems have been solved.", "Analyze job orders, drawings, blueprints, specifications, printed circuit board pattern films, and design data to calculate dimensions, tool selection, machine speeds, and feed rates.", "Write instruction sheets and cutter lists for a machine''s controller to guide setup and encode numerical control tapes."]'::jsonb,'["Computers and Electronics", "Mechanical", "Mathematics", "Production and Processing", "Engineering and Technology"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 41}, "experience": {"label": "4 to 6 years", "pct": 26}, "onsite_training": {"label": "6 months to 1 year", "pct": 21}, "on_the_job": {"label": "1 to 2 years", "pct": 21}}'::jsonb),
('53-4011','53-4011.00','{"en": "Drive electric, diesel-electric, steam, or gas-turbine-electric locomotives to transport passengers or freight. Interpret train orders, electronic or manual signals, and railroad rules and regulations."}'::jsonb,'["Interpret train orders, signals, or railroad rules and regulations that govern the operation of locomotives.", "Confer with conductors or traffic control center personnel via radiophones to issue or receive information concerning stops, delays, or oncoming trains.", "Receive starting signals from conductors and use controls such as throttles or air brakes to drive electric, diesel-electric, steam, or gas turbine-electric locomotives.", "Monitor gauges or meters that measure speed, amperage, battery charge, or air pressure in brake lines or in main reservoirs.", "Observe tracks to detect obstructions."]'::jsonb,'["Transportation", "Public Safety and Security", "English Language", "Education and Training", "Customer and Personal Service"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 68}, "experience": {"label": "1 to 2 years", "pct": 33}, "onsite_training": {"label": "3 to 6 months", "pct": 38}, "on_the_job": {"label": "3 to 6 months", "pct": 39}}'::jsonb),
('53-4031','53-4031.00','{"en": "Coordinate activities of switch-engine crew within railroad yard, industrial plant, or similar location. Conductors coordinate activities of train crew on passenger or freight trains. Yardmasters review train schedules and switching orders and coordinate activities of workers engaged in railroad traffic operations, such as the makeup or breakup of trains and yard switching."}'::jsonb,'["Signal engineers to begin train runs, stop trains, or change speed, using telecommunications equipment or hand signals.", "Confer with engineers regarding train routes, timetables, and cargoes, and to discuss alternative routes when there are rail defects or obstructions.", "Receive information regarding train or rail problems from dispatchers or from electronic monitoring devices.", "Receive instructions from dispatchers regarding trains'' routes, timetables, and cargoes.", "Direct and instruct workers engaged in yard activities, such as switching tracks, coupling and uncoupling cars, and routing inbound and outbound traffic."]'::jsonb,'["Public Safety and Security", "Transportation", "English Language", "Education and Training", "Law and Government"]'::jsonb,'{"job_zone": 2, "education": {"label": "High school diploma or GED", "pct": 86}, "experience": {"label": "None", "pct": 70}, "onsite_training": {"label": "3 to 6 months", "pct": 41}, "on_the_job": {"label": "3 to 6 months", "pct": 38}}'::jsonb),
('53-5031','53-5031.00','{"en": "Supervise and coordinate activities of crew engaged in operating and maintaining engines, boilers, deck machinery, and electrical, sanitary, and refrigeration equipment aboard ship."}'::jsonb,'["Monitor engine, machinery, or equipment indicators when vessels are underway, and report abnormalities to appropriate shipboard staff.", "Monitor the availability, use, or condition of lifesaving equipment or pollution preventatives to ensure that international regulations are followed.", "Monitor and test operations of engines or other equipment so that malfunctions and their causes can be identified.", "Start engines to propel ships, and regulate engines and power transmissions to control speeds of ships, according to directions from captains or bridge computers.", "Perform or participate in emergency drills, as required."]'::jsonb,'["Mechanical", "English Language", "Engineering and Technology", "Public Safety and Security", "Transportation"]'::jsonb,'{"job_zone": 3, "education": {"label": "High school diploma or GED", "pct": 48}, "experience": {"label": "1 to 2 years", "pct": 45}, "onsite_training": {"label": "6 months to 1 year", "pct": 29}, "on_the_job": {"label": "6 months to 1 year", "pct": 43}}'::jsonb),
('53-7021','53-7021.00','{"en": "Operate mechanical boom and cable or tower and cable equipment to lift and move materials, machines, or products in many directions."}'::jsonb,'["Determine load weights and check them against lifting capacities to prevent overload.", "Move levers, depress foot pedals, or turn dials to operate cranes, cherry pickers, electromagnets, or other moving equipment for lifting, moving, or placing loads.", "Inspect and adjust crane mechanisms or lifting accessories to prevent malfunctions or damage.", "Inspect cables or grappling devices for wear and install or replace cables, as needed.", "Direct helpers engaged in placing blocking or outrigging under cranes."]'::jsonb,'["Mechanical", "Mathematics", "Transportation", "English Language", "Public Safety and Security"]'::jsonb,'{"job_zone": 3, "education": {"label": "Post-secondary certificate", "pct": 61}, "experience": {"label": "2 to 4 years", "pct": 21}, "onsite_training": {"label": "1 to 3 months", "pct": 27}, "on_the_job": {"label": "1 to 3 months", "pct": 27}}'::jsonb))
insert into public.occupation_profiles(occupation_id,country_code,description,tasks,study_topics,typical_path,external_code,source_id,as_of)
select c.occupation_id,'US',v.description,v.tasks,v.topics,v.path,v.onet,'84650b67-bf2a-43dd-9ddd-f7525c933c75','2024-11-01'
from v join public.occupation_codes c on c.country_code='US' and c.code=v.soc;